{
  "moneyMethods": [
    "deposit: payable entry point; attached NEAR is credited to the caller's recorded balance in `balances`, and it reverts if deposits_paused is true or the attached deposit is zero",
    "withdraw: exit point; deducts `amount` from the caller's recorded balance and Promise::transfers that NEAR to a caller-chosen receiver_id (not restricted to the caller), so the contract account's actual NEAR leaves here",
    "balance_of: view only; reads any account's recorded balance, moves no money but is the ledger withdrawal draws on",
    "new: one-time init; moves no money but sets the owner account that later gates deposit pausing"
  ],
  "balanceStorage": [
    "balances: LookupMap<AccountId, NearToken> with prefix b\"b\" recording each depositor's credited NEAR; this internal ledger, not the account's actual chain balance, gates withdrawals",
    "deposits_paused: bool flag recording whether the deposit (inflow) path is blocked",
    "owner: AccountId recording who may call set_deposits_paused (controls inflow only, cannot touch balances or withdraw)"
  ],
  "privilegedMethods": [
    {
      "method": "new",
      "whoMayCall": "anyone, but only once on a fresh deployment; the deployer chooses the owner, and PanicOnDefault blocks non-init use of default state"
    },
    {
      "method": "set_deposits_paused",
      "whoMayCall": "only the stored owner (predecessor must equal self.owner); toggles deposits_paused and touches no balance"
    }
  ],
  "standingNote": "Inflow is deposit (owner-pausable), money sits as credited NEAR in the `balances` LookupMap while the real NEAR rests on the contract account, and outflow is only via the caller's own withdraw to any receiver; the code exposes no self-upgrade, no migration, and no owner path to funds. However, custody ultimately depends on the deployed account itself: a full-access key on that account could transfer away the actual NEAR backing the recorded balances or redeploy code that wipes or alters the `balances` ledger. Key and upgrade control has to be checked on the deployed account (access keys, lock/contract state) before this vault can be considered safe."
}

